# Python 3.6
from typing import List, Tuple


def f(n: int, adjacency_list: List[Tuple[int, int, List[int]]]) -> int:
    parent = list(range(n+1))
    rank = [0] * (n+1)

    def find(x):
        if parent[x]!= x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x!= root_y:
            if rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            elif rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    for u, k, vs in adjacency_list:
        for v in vs:
            union(u, v)

    return sum(rank)


if __name__ == '__main__':
    n = int(input())
    adjacency_list = []
    for _ in range(n):
        u, k, vs = map(int, input().split())
        adjacency_list.append((u, k, list(map(int, input().split()))))
    print(f(n, adjacency_list))
